import {newFn, slugify} from './slug';

import * as fs from 'fs';

function huntDCanon(v: unknown): unknown {
    if (v === undefined || v === null) {
        return null;
    }
    if (v instanceof Error) {
        return v.message;
    }
    if (typeof v === 'number') {
        return Number.isFinite(v) ? v : String(v);
    }
    if (typeof v === 'bigint') {
        return String(v);
    }
    if (typeof v === 'function' || typeof v === 'symbol') {
        return `[${typeof v}]`;
    }
    if (typeof v !== 'object') {
        return v;
    }
    if (v instanceof Date) {
        return Number.isNaN(v.getTime()) ? 'Invalid Date' : v.toISOString();
    }
    if (v instanceof Set) {
        return Array.from(v).map(huntDCanon).sort((a, b) => (JSON.stringify(a) < JSON.stringify(b) ? -1 : 1));
    }
    if (v instanceof Map) {
        return huntDCanon(Object.fromEntries(Array.from(v.entries()).map(([k, x]) => [String(k), x])));
    }
    if (Array.isArray(v)) {
        return v.map(huntDCanon);
    }
    const o = v as Record<string, unknown>;
    return Object.fromEntries(Object.keys(o).sort().map((k) => [k, huntDCanon(o[k])]));
}

function huntDRecord(name: string, i: number, input: unknown, call: () => unknown): void {
    const rec: Record<string, unknown> = {test: name, i, input: huntDCanon(input)};
    try {
        rec.output = huntDCanon(call());
    } catch (e) {
        rec.panic = e instanceof Error ? e.message : String(e);
    }
    const out = process.env.HUNT_DIFF_OUT;
    if (out) {
        fs.appendFileSync(out, JSON.stringify(rec) + '\n');
    }
}

function mulberry32(a: number) {
    return () => {
        a |= 0;
        a = (a + 0x6d2b79f5) | 0;
        let t = Math.imul(a ^ (a >>> 15), 1 | a);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

function inputs(seed: number): string[] {
    const rnd = mulberry32(seed);
    const alphabet = ['a', 'B', ' ', '_', '-', '1'];
    const out = ['', ' ', 'Hello World', 'snake_case'];
    for (let i = 0; i < 200; i++) {
        let s = '';
        for (let j = Math.floor(rnd() * 8); j > 0; j--) {
            s += alphabet[Math.floor(rnd() * alphabet.length)];
        }
        out.push(s);
    }
    return out;
}

describe('HuntD', () => {
    it('HuntD_slugify', () => {
        inputs(1).forEach((s, i) => huntDRecord('HuntD_slugify', i, s, () => slugify(s)));
    });

    it('HuntD_newFn', () => {
        const target: unknown = newFn;
        if (typeof target !== 'function') {
            throw new Error('target missing: newFn');
        }
        inputs(2).forEach((s, i) => huntDRecord('HuntD_newFn', i, s, () => newFn(s)));
    });
});
